<template><div class="space-y-4 p-4"><div><p class="text-[10px] font-bold uppercase tracking-widest text-indigo-500">Cebu Buyer</p><h1 class="mt-1 text-xl font-bold text-slate-800">Procurement workspace</h1></div><div class="grid grid-cols-3 gap-2"><NuxtLink v-for="card in cards" :key="card.to" :to="card.to" class="m-card p-3 text-center"><p class="text-xl font-bold text-indigo-600">{{ card.value }}</p><p class="text-[10px] text-slate-400">{{ card.label }}</p></NuxtLink></div><NuxtLink to="/buyer/post-request" class="m-btn-primary block text-center">Post a new request</NuxtLink><div class="m-card"><h2 class="text-sm font-bold text-slate-800">Recent requests</h2><NuxtLink v-for="item in requests.slice(0, 5)" :key="item.id" :to="`/buyer/requests/${item.id}`" class="mt-3 flex justify-between border-t border-slate-100 pt-3 text-xs"><span class="font-medium text-slate-700">{{ item.title }}</span><span class="text-slate-400">{{ item.status }}</span></NuxtLink></div><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">
definePageMeta({ middleware: ['auth'], alias: ['/buyer/home'] }); const api = useCommerce(); const requests = ref<any[]>([]); const orders = ref<any[]>([]); const notifications = ref<any[]>([]); const error = ref(''); const cards = computed(() => [{ label: 'Requests', value: requests.value.length, to: '/buyer/requests' }, { label: 'Orders', value: orders.value.length, to: '/buyer/orders' }, { label: 'Alerts', value: notifications.value.length, to: '/buyer/notifications' }]); onMounted(async () => { try { const [r, o, n] = await Promise.all([api.listProcurementRequests(), api.listOrders(), api.listNotifications('unread')]); requests.value = r.items.filter((item: any) => item.portal_key === 'cebu'); orders.value = o.items; notifications.value = n.items } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
